using System.Collections.Generic;
using Godot;
using Strata.Core.Content.Defs;

namespace Strata.Game.Items;

/// <summary>
/// Item icon textures (generated by tools/textures/build_icons.py for blocks and tools/blender for models),
/// loaded on demand from res://assets/icons/items/&lt;id&gt;.png. Missing icons are reported once and shown with a
/// generated "missing" texture so the gap is visible instead of silent.
/// </summary>
public static class ItemIcons
{
    private static readonly Dictionary<string, Texture2D> Cache = new();
    private static Texture2D? _missing;

    public static string PathFor(ItemDef item) => $"res://assets/icons/items/{item.Icon ?? item.Id}.png";

    public static Texture2D Get(ItemDef item)
    {
        if (Cache.TryGetValue(item.Id, out var tex)) return tex;
        var path = PathFor(item);
        if (ResourceLoader.Exists(path))
        {
            tex = GD.Load<Texture2D>(path);
        }
        else
        {
            GD.PushWarning($"Missing icon for item '{item.Id}' ({path}).");
            tex = MissingTexture;
        }
        Cache[item.Id] = tex;
        return tex;
    }

    /// <summary>A magenta checkerboard drawn in place of any absent generated texture (icons, UI sprites).</summary>
    public static Texture2D MissingTexture => _missing ??= CreateMissing();

    private static Texture2D CreateMissing()
    {
        var img = Image.CreateEmpty(16, 16, false, Image.Format.Rgba8);
        for (int y = 0; y < 16; y++)
            for (int x = 0; x < 16; x++)
                img.SetPixel(x, y, ((x / 4 + y / 4) & 1) == 0 ? new Color(1f, 0f, 1f) : new Color(0.1f, 0.1f, 0.1f));
        return ImageTexture.CreateFromImage(img);
    }
}
